package org.jarvisassistant.app;
import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.Color;
import android.net.Uri;
import android.os.*;
import android.provider.Settings;
import android.view.*;
import android.widget.*;
import java.util.concurrent.*;

/** The same first-party updater on phones and watches. No installation bypass. */
public final class AppUpdatesActivity extends Activity {
    static volatile AppUpdatesActivity visible;
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private volatile AppReleases.Source source;private TextView status;private Button download,install,permission;private boolean resumed;private volatile boolean checking;
    private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
    @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);boolean watch=AppReleases.watch(this);ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(0xff0c1b20);scroll.setVerticalScrollBarEnabled(false);LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(watch?28:24),dp(watch?24:32),dp(watch?28:24),dp(36));scroll.addView(body);setContentView(scroll);
        if(!watch){scroll.setOnApplyWindowInsetsListener((view,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets safe=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());view.setPadding(safe.left,safe.top,safe.right,safe.bottom);}else view.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});scroll.requestApplyInsets();}
        TextView title=text("JARVIS updates",watch?19:28);title.setTypeface(android.graphics.Typeface.create("sans-serif-medium",android.graphics.Typeface.NORMAL));title.setAccessibilityHeading(true);body.addView(title);String current="";try{current=getPackageManager().getPackageInfo(getPackageName(),0).versionName;}catch(Exception ignored){}TextView version=text("Installed · "+current,13);version.setTextColor(0xfff0b998);body.addView(version);status=text("Check your private release channel.",14);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);status.setPadding(dp(16),dp(16),dp(16),dp(16));android.graphics.drawable.GradientDrawable panel=new android.graphics.drawable.GradientDrawable();panel.setColor(0xff132a30);panel.setCornerRadius(dp(18));status.setBackground(panel);LinearLayout.LayoutParams statusSize=new LinearLayout.LayoutParams(-1,-2);statusSize.topMargin=dp(14);statusSize.bottomMargin=dp(10);body.addView(status,statusSize);
        button(body,"Check now",this::check);download=button(body,"Download update",()->{AppUpdates.downloadNow(this);render();});install=button(body,"Install verified update",()->{AppReleases.Release release=AppReleases.cached(this);if(release==null||!AppUpdates.working.compareAndSet(false,true))return;render();worker.execute(()->{try{AppUpdates.install(this,release,false);}catch(Exception e){AppUpdates.status(this,e instanceof java.io.IOException?e.getMessage():"Could not start the verified update. Try again from this screen.");}AppUpdates.working.set(false);main.post(this::render);});});
        Switch automatic=new Switch(this);automatic.setText("Automatic updates");automatic.setTextColor(0xffe5f3ed);automatic.setTextSize(14);automatic.setPadding(0,dp(16),0,dp(16));automatic.setChecked(AppReleases.preferences(this).getBoolean("automatic",false));body.addView(automatic);automatic.setOnCheckedChangeListener((view,enabled)->{AppUpdates.schedule(this,enabled);if(enabled){AppUpdates.status(this,"Automatic checks enabled · Wi-Fi, healthy battery, about every 6 hours. Allow JARVIS installation below for automatic installs.");if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},185);}render();});
        permission=button(body,"Allow JARVIS updates",()->{try{startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())));}catch(ActivityNotFoundException e){AppUpdates.status(this,"This device does not offer the installation-permission screen. Check updates here; Android may require a manual installer confirmation.");render();}});
        body.addView(text((watch?"Keep the paired phone's JARVIS watch connection enabled. ":"")+"Only newer APKs signed by this installed JARVIS publisher are accepted. Android can still require a confirmation. Updates preserve app data; active voice or control sessions may end. Your microphone is never started by the updater.",12));button(body,"Back",this::finish);
    }
    private TextView text(String value,int size){TextView text=new TextView(this);text.setText(value);text.setTextSize(size);text.setTextColor(0xffeff5f2);text.setIncludeFontPadding(false);text.setLineSpacing(dp(2),1);text.setPadding(0,dp(8),0,dp(8));if(AppReleases.watch(this))text.setGravity(Gravity.CENTER);return text;}
    private Button button(LinearLayout parent,String label,Runnable action){boolean primary=label.equals("Check now")||label.equals("Install verified update");Button button=new Button(this);button.setAllCaps(false);button.setText(label);button.setTextSize(14);button.setTypeface(android.graphics.Typeface.create("sans-serif-medium",android.graphics.Typeface.NORMAL));button.setTextColor(primary?0xff0c1b20:0xffeff5f2);button.setMinHeight(dp(50));button.setPadding(dp(12),dp(12),dp(12),dp(12));button.setElevation(0);button.setStateListAnimator(null);android.graphics.drawable.GradientDrawable shape=new android.graphics.drawable.GradientDrawable();shape.setColor(primary?0xffaedecf:0xff1c353b);shape.setCornerRadius(dp(AppReleases.watch(this)?25:16));button.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x33aedecf),shape,null));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(8);parent.addView(button,lp);button.setOnClickListener(v->action.run());return button;}
    private void check(){if(checking)return;checking=true;AppUpdates.status(this,"Checking for a published release…");render();worker.execute(()->{try(AppReleases.Source client=new AppReleases.Source(this,false)){source=client;AppUpdates.check(this,client);}catch(Exception e){AppUpdates.status(this,e instanceof java.io.IOException?e.getMessage():"No release could be read. Check the phone connection and private release channel.");}finally{source=null;checking=false;main.post(this::render);}});}
    private void render(){if(!resumed)return;status.setText(AppReleases.preferences(this).getString("status","Check your private release channel."));AppReleases.Release release=AppReleases.cached(this);download.setVisibility(release==null?View.GONE:View.VISIBLE);download.setEnabled(!AppUpdates.working.get()&&!checking);install.setVisibility(release!=null&&AppReleases.apk(this).exists()?View.VISIBLE:View.GONE);install.setEnabled(!AppUpdates.working.get()&&!checking);permission.setVisibility(getPackageManager().canRequestPackageInstalls()?View.GONE:View.VISIBLE);}
    private final Runnable refresh=new Runnable(){public void run(){if(resumed){render();main.postDelayed(this,700);}}};
    @Override protected void onResume(){super.onResume();resumed=true;visible=this;refresh.run();}
    @Override protected void onPause(){resumed=false;if(visible==this)visible=null;main.removeCallbacks(refresh);super.onPause();}
    @Override protected void onDestroy(){AppReleases.Source client=source;if(client!=null)client.close();worker.shutdownNow();main.removeCallbacksAndMessages(null);super.onDestroy();}
}
